from __future__ import annotations

import json
import logging


class ExecutionContext(logging.Filter):

    execution_id: str | None = None
    data: dict = {}

    def filter(self, record: logging.LogRecord) -> bool:
        """
        Update the record with the execution context
        """
        if record.levelname.upper() == "RADAR" and record.name.lower() == "root":
            record.execution_context = ExecutionContext.data.copy()  # can't be reference needs to be a copy
            return True
        return False

    @classmethod
    def update_execution_id(cls, execution_id: str | None) -> None:
        cls.execution_id = execution_id
        cls.data["execution_id"] = execution_id

    @classmethod
    def update_test_case_name(cls, name: str) -> None:
        cls.data.update({"tc_name": name})

    @classmethod
    def update_suite_name(cls, name: str) -> None:
        cls.data.update({"suite_name": name})

    @classmethod
    def update_suite_path(cls, path: str | None) -> None:
        cls.data.update({"suite_path": path})

    @classmethod
    def update_username(cls, username: str | None) -> None:
        cls.data.update({"username": username})

    @classmethod
    def update_repository(cls, env_cm_artifacts: str | None) -> None:
        if not env_cm_artifacts:
            return
        try:
            cm_artifacts: list = json.loads(env_cm_artifacts)
            test_repository_artifact: dict = next(
                artifact for artifact in cm_artifacts if artifact["type"] == "testrepository"
            )
            repo = test_repository_artifact["properties"]["repository"]
            repo = repo.replace("MN/UTE/", "")
            repo = repo.replace("gears/", "")
        except Exception:
            repo = None

        cls.data.update({"repository": repo})


context = ExecutionContext()
